     7→
     8→export const getMessageType = (event: EventTimelineItem): ForwardMessageType => {
     9→  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    10→    const kind = event.content.inner.content.kind;
    11→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    12→      const msgType = kind.inner.content.msgType;
    13→
    14→      if (msgType?.tag === MessageType_Tags.Text) {
    15→        return "text";
    16→      }
    17→
    18→      if (msgType?.tag === MessageType_Tags.Image) {
    19→        return "image";
    20→      }
    21→
    22→      if (msgType?.tag === MessageType_Tags.Video) {
    23→        return "video";
    24→      }
    25→
    26→      if (msgType?.tag === MessageType_Tags.Audio) {
    27→        return "audio";
    28→      }
    29→
    30→      if (msgType?.tag === MessageType_Tags.File) {
    31→        return "file";
    32→      }
    33→    }
    34→  }
    35→
    36→  return "text";
    37→};
