    95→    try {
    96→      const dataExists = await RNFS.exists(dataPath);
    97→      const cacheExists = await RNFS.exists(cachePath);
    98→
    99→      if (dataExists) {
   100→        await RNFS.unlink(dataPath);
   101→        console.log("Cleared crypto data store");
   102→      }
   103→
   104→      if (cacheExists) {
   105→        await RNFS.unlink(cachePath);
   106→        console.log("Cleared crypto cache store");
   107→      }
   108→    } catch (error) {
   109→      console.warn("Failed to clear crypto store:", error);
