   134→  /** Attempt to restore session from stored credentials */
   135→  public static restoreSession = async (): Promise<boolean> => {
   136→    try {
   137→      const credentials = MatrixStorage.getLoginCredentials();
   138→
   139→      if (!credentials) return false;
   140→
   141→      await this.initialize(credentials.baseUrl);
   142→
   143→      if (!this.instance) throw new Error("Failed to initialize client");
   144→
   145→      // Create client with stored credentials
   146→      await this.instance.restoreSession({
   147→        accessToken: credentials.accessToken,
   148→        refreshToken: credentials.refreshToken,
   149→        userId: credentials.userId,
   150→        deviceId: credentials.deviceId,
   151→        homeserverUrl: credentials.baseUrl,
   152→        oidcData: undefined,
   153→        slidingSyncVersion: SlidingSyncVersion.Native,
   154→      });
   155→
   156→      // Verify the session is valid by making a server request
   157→      try {
   158→        this.profile = await this.instance.getProfile(credentials.userId);
   159→      } catch (error) {
   160→        console.warn("Session validation failed:", error);
   161→        throw new Error("Session is invalid or expired");
   162→      }
   163→
   164→      this.syncService = await this.instance.syncService().finish();
   165→
   166→      if (!this.syncService) {
   167→        throw new Error("Failed to initialize sync service");
   168→      }
   169→
   170→      await this.syncService.start();
   171→
   172→      // Update atoms so providers can react to the initialized service
   173→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   174→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   175→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   176→
   177→      return true;
   178→    } catch (error) {
   179→      console.warn("Failed to restore session:", error);
   180→
   181→      // Clear both credentials and crypto store to ensure clean state
   182→      MatrixStorage.clearLoginCredentials();
   183→      await this.clearCryptoStore();
   184→
   185→      // Reset the instance so it can be recreated fresh
   186→      this.instance = null;
   187→      this.syncService = null;
   188→
   189→      // Clear atoms
   190→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   191→      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   192→
   193→      return false;
   194→    }
