   197→  /** Call this after logging in to create a new client instance with the provided account.  */
   198→  public static setup = async (params: Session) => {
   199→    // Clear any existing crypto store to prevent device ID mismatches
   200→    await this.clearCryptoStore();
   201→
   202→    // Stop and clear existing instances
   203→    if (this.syncService) await this.syncService.stop();
   204→    this.instance = null;
   205→    this.syncService = null;
   206→
   207→    // Save credentials for future auto-login
   208→    MatrixStorage.saveLoginCredentials({
   209→      accessToken: params.accessToken,
   210→      refreshToken: params.refreshToken,
   211→      userId: params.userId,
   212→      deviceId: params.deviceId,
   213→      baseUrl: params.homeserverUrl,
   214→    });
   215→
   216→    // Create a fresh client instance and configure it with the session + sliding sync
   217→    await this.initialize(params.homeserverUrl);
   218→
   219→    if (!this.instance) throw new Error("Failed to initialize client");
   220→
   221→    // Use local variable to help TypeScript with type narrowing
   222→    const client: ClientInterface = this.instance;
   223→
   224→    await client.restoreSession({
   225→      accessToken: params.accessToken,
   226→      refreshToken: params.refreshToken,
   227→      userId: params.userId,
   228→      deviceId: params.deviceId,
   229→      homeserverUrl: params.homeserverUrl,
   230→      oidcData: undefined,
   231→      slidingSyncVersion: SlidingSyncVersion.Native,
   232→    });
   233→
   234→    // Verify the session is valid by making a server request
   235→    // Use the params.userId since client.userId() might not be populated yet
   236→    try {
   237→      this.profile = await client.getProfile(params.userId);
   238→    } catch (error) {
   239→      console.warn("Session validation failed:", error);
   240→      throw new Error("Session is invalid or expired");
   241→    }
   242→
   243→    this.syncService = await client.syncService().finish();
   244→
   245→    if (!this.syncService) throw new Error("Failed to initialize sync service");
   246→
   247→    await this.syncService.start();
   248→    await client.encryption().waitForE2eeInitializationTasks();
   249→
   250→    // Check if we need to bootstrap cross-signing or enable backups
   251→    try {
   252→      const encryption = client.encryption();
   253→      const backupExists = await encryption.backupExistsOnServer();
   254→      console.log("Backup exists on server:", backupExists);
   255→      console.log(
   256→        "Current verification state:",
   257→        encryption.verificationState(),
   258→      );
   259→
   260→      // If no backup exists and we're the only device, we might need to set one up
   261→      const isLastDevice = await encryption.isLastDevice();
   262→      console.log("Is last device:", isLastDevice);
   263→
   264→      if (!backupExists) {
   265→        console.log("Enabling backups for cross-signing...");
   266→        await encryption.enableBackups();
   267→      }
   268→
   269→      // Update atoms so providers can react to the initialized service
   270→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   271→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   272→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   273→    } catch (error) {
   274→      console.warn("Failed to check backup/verification status:", error);
   275→    }
   276→  };
