   437→  public static deactivateAccount = async (password: string) => {
   438→    if (!this.instance) throw new Error("Client not initialized");
   439→
   440→    try {
   441→      // First request with undefined auth_data (will always fail per UIA spec)
   442→      try {
   443→        await this.instance.deactivateAccount(undefined, true);
   444→      } catch {
   445→        // Expected to fail
   446→      }
   447→
   448→      console.log(this.instance.userId(), "userId");
   449→      const userId = this.instance.userId();
   450→      if (!userId) throw new Error("User ID not found");
   451→
   452→      const authData = new AuthData.Password({
   453→        passwordDetails: AuthDataPasswordDetails.create({
   454→          identifier: userId,
   455→          password,
   456→        }),
   457→      });
   458→
   459→      // Step 4: Second request with auth data
   460→      await this.instance.deactivateAccount(authData, true);
   461→
   462→      // After successful deactivation, clean up local data
   463→      await this.logout();
   464→    } catch (error) {
   465→      console.error("Failed to deactivate account:", error);
   466→      throw error;
   467→    }
   468→  };
