   929→  public static getReadReceipts = async (event: EventTimelineItem) => {
   930→    const userIds = Array.from(event.readReceipts.keys()).map(
   931→      (userIds) => userIds,
   932→    );
   933→
   934→    // Don't show read receipts for the sender's own message
   935→    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);
   936→
   937→    if (!filteredUserIds.length) {
   938→      return [];
   939→    }
   940→
   941→    try {
   942→      const profilePromises = filteredUserIds.map((userId) =>
   943→        this.instance?.getProfile(userId),
   944→      );
   945→      const profiles = await Promise.allSettled(profilePromises);
   946→      return profiles
   947→        .filter((p) => p.status === "fulfilled")
   948→        .map((p) => p.value)
   949→        .filter((p) => p !== undefined);
   950→    } catch (error) {
   951→      console.error("Failed to get read receipt users:", error);
   952→      return [];
   953→    }
   954→  };
