    19→
    20→interface Props {
    21→  event: EventTimelineItem;
    22→  isPreviousSameSender: boolean;
    23→}
    24→
    25→const getEventType = (event: EventTimelineItem) => {
    26→  if (
    27→    event.content.tag === TimelineItemContent_Tags.RtcNotification ||
    28→    event.content.tag === TimelineItemContent_Tags.CallInvite
    29→  ) {
    30→    return "call";
    31→  }
    32→  if (event.content.tag === TimelineItemContent_Tags.State) {
    33→    const stateContent = event.content.inner.content;
    34→    // This was used to handle call events in older versions of the SDK. Might be useful in the future.
    35→    // if (
    36→    //   stateContent.tag === OtherState_Tags.Custom &&
    37→    //   stateContent.inner?.eventType === "org.matrix.msc3401.call.member"
    38→    // ) {
    39→    //   return "call";
    40→    // }
    41→
    42→    if (stateContent.tag.includes("Room")) return "room";
    43→  }
    44→
    45→  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    46→    const kind = event.content.inner.content.kind;
    47→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    48→      const msgType = kind.inner.content.msgType;
    49→
    50→      if (msgType?.tag === MessageType_Tags.Text) {
    51→        return "text";
    52→      } else if (msgType?.tag === MessageType_Tags.Image) {
    53→        return "image";
    54→      } else if (msgType?.tag === MessageType_Tags.File) {
    55→        return "file";
    56→      } else if (msgType?.tag === MessageType_Tags.Video) {
    57→        return "video";
    58→      } else if (msgType?.tag === MessageType_Tags.Audio) {
    59→        return "audio";
    60→      } else if (msgType?.tag === MessageType_Tags.Other) {
    61→        return "other";
    62→      } else {
    63→        return "unkown";
    64→      }
    65→    }
    66→
    67→    if (kind?.tag === MsgLikeKind_Tags.UnableToDecrypt) {
    68→      return "unableToDecrypt";
    69→    }
    70→
    71→    if (kind?.tag === MsgLikeKind_Tags.Redacted) {
    72→      return "redacted";
    73→    }
    74→  }
    75→  if (event.content.tag === TimelineItemContent_Tags.RoomMembership) {
    76→    return "membership";
    77→  }
    78→  if (event.content.tag === TimelineItemContent_Tags.ProfileChange) {
    79→    return "profile";
    80→  }
    81→  return "unkown";
    82→};
    83→
    84→export const SingleMessageType: FC<Props> = ({
    85→  event,
    86→  isPreviousSameSender,
    87→}) => {
    88→  if (!event) return null;
    89→
    90→  switch (getEventType(event)) {
    91→    case "text": {
    92→      return (
    93→        <TextMessage
    94→          event={event}
    95→          isPreviousSameSender={isPreviousSameSender}
    96→        />
    97→      );
    98→    }
    99→    case "image": {
   100→      return (
   101→        <ImageMessage
   102→          event={event}
   103→          isPreviousSameSender={isPreviousSameSender}
   104→        />
   105→      );
   106→    }
   107→    case "audio": {
   108→      return (
   109→        <VoiceMessage
   110→          event={event}
   111→          isPreviousSameSender={isPreviousSameSender}
   112→        />
   113→      );
   114→    }
   115→    case "video": {
   116→      return (
   117→        <VideoMessage
   118→          event={event}
   119→          isPreviousSameSender={isPreviousSameSender}
   120→        />
   121→      );
   122→    }
   123→    case "other": {
   124→      return <OtherMessage event={event} />;
   125→    }
   126→    case "call": {
   127→      return (
   128→        <CallMessage
   129→          event={event}
   130→          isPreviousSameSender={isPreviousSameSender}
   131→        />
   132→      );
   133→    }
   134→    case "membership": {
   135→      return <MembershipInfoMessage event={event} />;
   136→    }
   137→    case "profile": {
   138→      return <ProfileInfoMessage event={event} />;
   139→    }
   140→    case "room": {
   141→      return <RoomInfoMessage event={event} />;
   142→    }
   143→    case "unableToDecrypt": {
   144→      return <UnableToDecryptMessage event={event} />;
   145→    }
   146→    case "redacted": {
   147→      return (
   148→        <DeletedMessage
   149→          event={event}
   150→          isPreviousSameSender={isPreviousSameSender}
   151→        />
   152→      );
   153→    }
   154→    default:
   155→      return null;
   156→  }
   157→};
