     1→import { Block, useAnimateParallel } from "@prototyp/skeletor";
     2→import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
     3→import { useSetAtom } from "jotai";
     4→import { getMessageType } from "modules/matrix-client/utils";
     5→import { TimelineAtoms } from "modules/timeline";
     6→import { type ReactNode, useCallback } from "react";
     7→import { Vibration } from "react-native";
     8→import { Gesture, GestureDetector } from "react-native-gesture-handler";
     9→import { Easing, runOnJS } from "react-native-reanimated";
    10→
    11→interface Props {
    12→  children: ReactNode;
    13→  event: EventTimelineItem;
    14→  content: string;
    15→  onStart?: () => void;
    16→  onFinalize?: () => void;
    17→}
    18→
    19→export const MessageLongPressWrapper: React.FC<Props> = ({
    20→  children,
    21→  event,
    22→  content,
    23→  onStart,
    24→  onFinalize,
    25→}) => {
    26→  const scale = useAnimateParallel(
    27→    { scaleX: [1, 1.1], scaleY: [1, 1.1] },
    28→    { duration: 700, easing: Easing.bezierFn(0.31, 0.04, 0.03, 1.04) },
    29→  );
    30→  const setLongPressPayload = useSetAtom(TimelineAtoms.longPressPayload);
    31→
    32→  const openSheet = useCallback(() => {
    33→    const messageType = getMessageType(event);
    34→    setLongPressPayload({ event, content, messageType });
    35→  }, [content, event, setLongPressPayload]);
    36→
    37→  const vibrateEnd = useCallback(() => {
    38→    Vibration.vibrate(1);
    39→  }, []);
    40→
    41→  const longPress = Gesture.LongPress()
    42→    .minDuration(500)
    43→    .onBegin(() => {
    44→      runOnJS(scale.start)();
    45→      if (!onStart) return;
    46→      runOnJS(onStart)();
    47→    })
    48→    .onStart(() => {
    49→      runOnJS(openSheet)();
    50→      runOnJS(vibrateEnd)();
    51→    })
    52→    .onTouchesCancelled(() => {
    53→      runOnJS(scale.reverse)();
    54→    })
    55→    .onFinalize((_, success) => {
    56→      runOnJS(scale.reverse)();
    57→      if (onFinalize && !success) {
    58→        runOnJS(onFinalize)();
    59→      }
    60→    });
    61→
    62→  if (!event.canBeRepliedTo) return <>{children}</>;
    63→
    64→  return (
    65→    <>
    66→      <GestureDetector gesture={longPress}>
    67→        <Block animations={scale.animations}>{children}</Block>
    68→      </GestureDetector>
    69→    </>
    70→  );
    71→};
